"""Presentation-layer UI for research AI Agent, keeping research provenance in the backend.

The dashboard separates company-registered inventory counts from controlled
agent test cases; it does not make assertions of commercial production readiness.
"""
PAGE = "<!doctype html>\n<html lang=\"id\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>PT Liliang International | AI Agent Intelligence</title>\n<link rel=\"icon\" href=\"/branding/logo?v=20261020\">\n<style>\n:root{font:14px/1.55 system-ui,-apple-system,\"Segoe UI\",Arial,sans-serif;color:#162b48;background:#f2f6fb}\n*{box-sizing:border-box}body{margin:0}button,select{font:inherit}a{color:inherit;text-decoration:none}\n.page{display:flex;min-height:100vh}\n.sidebar{width:236px;flex:0 0 236px;background:#10213e;color:#dce8fb;padding:24px 15px 20px;display:flex;flex-direction:column;gap:10px}\n.brand{display:flex;align-items:center;gap:9px;border-bottom:1px solid #2c4264;padding:5px 7px 24px;margin-bottom:14px}\n.brand img{height:55px;width:75px;object-fit:contain;background:#090f1c;border-radius:9px}\n.brand strong{display:block;font-size:13px;color:#fff;line-height:1.35}.brand small{font-size:10px;color:#9ab5d8;letter-spacing:.08em}\n.navtitle{font-size:10px;letter-spacing:.15em;color:#85a4ce;margin:13px 9px 4px;font-weight:800}\n.nav{display:flex;align-items:center;gap:10px;padding:12px;color:#b6ccec;font-size:12px;font-weight:750;border-radius:9px}\n.nav.current,.nav:hover{background:#275080;color:#fff}\n.nav .glyph{width:22px;text-align:center;font-size:16px}\n.sidefoot{margin-top:auto;border-top:1px solid #2c4264;padding:20px 6px 0;font-size:11px;color:#9ab5d8}\n.sidefoot .dot{display:inline-block;width:8px;height:8px;background:#32b997;border-radius:50%;margin-right:6px}\n.main{min-width:0;flex:1}\n.topbar{height:74px;border-bottom:1px solid #e0e8f2;background:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 35px}\n.topbar strong{font-size:14px}.topbar small{color:#8899ad}.topbar .right{display:flex;align-items:center;gap:15px}\n.tag{display:inline-flex;align-items:center;gap:6px;padding:5px 11px;border-radius:100px;font-size:10px;font-weight:800;background:#ebf3fd;color:#2763a1}\n.tag.ok{background:#e6f7ee;color:#0f865c}.tag.warn{background:#fff2da;color:#906018}.tag.neutral{background:#eff3f8;color:#526981}\n.wrap{max-width:1450px;margin:0 auto;padding:27px 35px 45px}\n.breadcrumb{font-size:11px;color:#7f91aa;margin-bottom:18px}.breadcrumb a{color:#2b65a5}\n.hero{position:relative;overflow:hidden;background:linear-gradient(114deg,#14305a 0%,#1b4c86 75%,#256b9d 100%);border-radius:17px;color:#fff;padding:31px 35px;min-height:182px}\n.hero:after{content:\"\";position:absolute;right:-45px;top:-84px;width:310px;height:310px;border:1px solid #ffffff2c;border-radius:50%;box-shadow:0 0 0 49px #ffffff09,0 0 0 96px #ffffff07}\n.kicker{color:#aacefa;font-size:11px;font-weight:800;letter-spacing:.14em}\n.hero h1{font-size:32px;letter-spacing:-.045em;line-height:1.2;margin:9px 0 11px;max-width:570px}\n.hero p{font-size:13px;color:#d9e9fb;max-width:690px;margin:0;position:relative;z-index:1}\n.hero .hero-label{display:inline-flex;background:#ffffff26;border:1px solid #ffffff3d;padding:5px 12px;border-radius:99px;margin-top:20px;font-size:11px;font-weight:700}\n.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin:17px 0 23px}\n.metric{background:#fff;border:1px solid #dfe8f2;border-radius:13px;padding:19px 20px;min-width:0}\n.metric .small{color:#8297b2;font-size:10px;letter-spacing:.08em;font-weight:800;margin-bottom:10px}\n.metric b{display:block;font-size:16px;margin-bottom:5px}.metric small{color:#7c8fa5;font-size:11px}\n.grid{display:grid;grid-template-columns:minmax(0,1.16fr) minmax(0,.84fr);gap:17px}\n.card{background:#fff;border:1px solid #e0e9f4;border-radius:14px;padding:23px 24px;min-width:0;margin-bottom:17px;box-shadow:0 2px 12px #17345d06}\n.card h2{font-size:17px;margin:0 0 7px}.sub{color:#7b91a9;font-size:12px;margin:0 0 14px}\n.sectionhead{display:flex;justify-content:space-between;gap:12px;align-items:center;margin:0 0 15px}\n.sectionhead h2{margin:0}\nlabel{display:block;color:#345273;font-weight:750;font-size:11px;margin:13px 0 6px}\nselect{width:100%;border:1px solid #cddcec;background:#fff;border-radius:10px;color:#163757;padding:12px 14px;cursor:pointer;min-height:45px}\ninput.stockinput{min-height:45px;border:1px solid #cddcec;border-radius:10px;\ncolor:#163757;background:#fff;padding:11px 13px;flex:1;min-width:190px;max-width:310px}\n.inventorytable{margin-top:14px}\n.datascope{color:#53708f;font-size:11px;margin:10px 0 0}\nbutton{border:0;cursor:pointer}\n.primary{padding:12px 17px;border-radius:10px;background:#2569ba;color:#fff;font-weight:800;font-size:12px}\n.primary:hover{background:#1b589e}.primary:disabled{opacity:.55;cursor:default}\n.secondary{padding:10px 14px;border-radius:9px;background:#eef4fb;color:#275d9d;font-weight:750;font-size:12px}\n.notice{background:#f4f8fd;border-left:3px solid #4b8acb;border-radius:6px;padding:13px 16px;color:#526e8d;font-size:11px}\n.row{display:flex;align-items:center;gap:10px;flex-wrap:wrap}\n.rightalign{margin-left:auto}\n.statusline{font-size:11px;color:#7089a3;margin-top:15px}\n.err{color:#a6323a}\n.labeltitle{font-size:11px;color:#7b90a8;text-transform:uppercase;letter-spacing:.1em;font-weight:850}\n.inquiryquote{background:#f6f9fd;border:1px solid #e5edf6;border-radius:10px;padding:15px 17px;color:#27415f;font-weight:550;font-size:13px}\n.empty{padding:31px 16px;color:#8799af;text-align:center;border:1px dashed #d7e1ec;border-radius:11px;background:#fafcfe}\n.result{display:none}.result.show{display:block}\n.resultgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}\n.module{padding:22px}.module .icon{width:35px;height:35px;display:grid;place-items:center;background:#e7f0ff;color:#2f63aa;font-weight:900;border-radius:10px}\n.modhead{display:flex;align-items:center;gap:12px;margin-bottom:16px}.modhead h3{margin:0;font-size:14px}.modhead small{color:#8297aa}\n.kv{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}\n.kv div{background:#f6f9fd;border-radius:9px;padding:11px 13px}.kv small{display:block;color:#8395a8;font-size:11px}.kv b{font-size:13px;display:block;word-break:break-word}\ntable{width:100%;border-collapse:collapse;font-size:11px}\nth,td{text-align:left;padding:10px;border-bottom:1px solid #eaf0f6;vertical-align:middle}\nth{color:#6d859e;background:#f5f8fc;font-weight:800}\n.tablewrap{overflow:auto}\n.muted{font-size:11px;color:#8194a8}\n.minirow{display:flex;justify-content:space-between;gap:10px;border-bottom:1px solid #edf2f7;padding:10px 0;font-size:12px}\n.minirow:last-child{border-bottom:0}\n.bars{display:flex;gap:10px;align-items:end;height:102px;margin-top:8px}\n.barbox{flex:1;text-align:center;color:#718aa1;font-size:10px}\n.bar{height:40px;background:linear-gradient(#4587d2,#2968ae);border-radius:6px 6px 2px 2px;margin:5px auto;width:72%;max-width:54px}\n.agentText{white-space:normal;line-height:1.9;font-size:13px;color:#38516b}\n.agentText div{margin-bottom:10px}.agentText strong{color:#173859}\n.researchnote{font-size:11px;color:#667f99;background:#f7f9fd;border:1px solid #e7edf6;padding:15px 19px;border-radius:11px;margin-top:7px}\n.footer{color:#8a9bad;font-size:11px;margin:28px 0 0}\n.footgrid{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.viewlog{display:none;margin-top:14px}.viewlog pre{white-space:pre-wrap;overflow:auto;max-height:350px;background:#101f35;color:#d5e7fe;padding:16px;font-size:11px;border-radius:10px}\n@media(max-width:1050px){.sidebar{width:185px;flex-basis:185px}.wrap{padding:20px}.topbar{padding:0 20px}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.grid{grid-template-columns:1fr}}\n@media(max-width:720px){.sidebar{display:none}.topbar{height:auto;min-height:60px;padding:13px 16px}.topbar .right{font-size:10px}.wrap{padding:14px}.hero{padding:25px}.hero h1{font-size:26px}.stats,.resultgrid,.kv,.footgrid{grid-template-columns:1fr}.card{padding:19px}}\n@media print{.sidebar,.topbar,.controls,.footer,button{display:none!important}.main{width:100%}.result{display:block}.card,.metric{break-inside:avoid}}\n</style></head>\n<body><div class=\"page\">\n<aside class=\"sidebar\">\n<div class=\"brand\"><img src=\"/branding/logo?v=20261020\" alt=\"PT Liliang\"><div><strong>PT LILIANG<br>INTERNATIONAL</strong><small>ENTERPRISE INTELLIGENCE</small></div></div>\n<div class=\"navtitle\">AI CAPABILITIES</div>\n<a class=\"nav current\" href=\"/ai/agent-pilot\"><span class=\"glyph\">✦</span>AI Agent Orchestrator</a>\n<a class=\"nav\" href=\"/ai/inquiry-advisor\"><span class=\"glyph\">◈</span>Inquiry Intelligence Advisor</a>\n<a class=\"nav\" href=\"/workspace\"><span class=\"glyph\">◈</span>Multi-AI Workspace</a>\n<a class=\"nav\" href=\"/ai/hybrid\"><span class=\"glyph\">◇</span>Hybrid Semantic Lab</a>\n<a class=\"nav\" href=\"/ai/evidence\"><span class=\"glyph\">▤</span>Research Evidence</a>\n<div class=\"navtitle\">ENTERPRISE OPERATIONS</div>\n<a class=\"nav\" href=\"/transactions\"><span class=\"glyph\">▣</span>Transaksi & Approval</a>\n<a class=\"nav\" href=\"/catalog\"><span class=\"glyph\">▦</span>Product Catalog</a>\n<a class=\"nav\" href=\"/stock/reference\"><span class=\"glyph\">◉</span>Stok & Kemasan</a>\n<div class=\"sidefoot\"><span class=\"dot\"></span>RESEARCH INTEGRATION PILOT<br>PT Liliang · Magister Informatika</div>\n</aside>\n<div class=\"main\">\n<header class=\"topbar\"><div><strong>AI Agent Intelligence</strong><br><small>Enterprise Research Platform · Capstone Project</small></div><div class=\"right\"><span class=\"tag ok\">● Groq Integration</span><a class=\"secondary\" href=\"/workspace\">Kembali ke ERP</a></div></header>\n<div class=\"wrap\">\n<div class=\"breadcrumb\"><a href=\"/workspace\">ERP</a> / Artificial Intelligence / AI Agent Orchestrator</div>\n<section class=\"hero\"><div class=\"kicker\">INTELLIGENT ENTERPRISE ORCHESTRATION</div>\n<h1>Satu Agent. Empat Kapabilitas AI.</h1>\n<p>Integrasi AI untuk memahami kebutuhan flavor pelanggan, memeringkat produk, mengeksplorasi keterkaitan SKU, dan menganalisis proyeksi permintaan dalam satu alur pengambilan keputusan.</p>\n<div class=\"hero-label\">GROQ LLM · PYDANTICAI · HUMAN-IN-THE-LOOP</div></section>\n<div class=\"stats\">\n<div class=\"metric\"><div class=\"small\">AI-01 · LANGUAGE INTELLIGENCE</div><b>Requirement Interpreter</b><small>Normalisasi atribut inquiry</small></div>\n<div class=\"metric\"><div class=\"small\">AI-02 · INFORMATION RETRIEVAL</div><b>Product Matching</b><small>BM25 candidate ranking</small></div>\n<div class=\"metric\"><div class=\"small\">AI-03 · SALES INTELLIGENCE</div><b>Product Bundling</b><small>Association-rule analysis</small></div>\n<div class=\"metric\"><div class=\"small\">AI-04 · PREDICTIVE ANALYTICS</div><b>Demand Forecasting</b><small>Moving-average baseline</small></div>\n</div>\n<div class=\"grid\">\n<section class=\"card controls\"><div class=\"sectionhead\"><h2>Jalankan Analisis AI Agent</h2><span class=\"tag\">EXPERIMENTAL UAT</span></div>\n<p class=\"sub\">Pilih skenario yang sudah ditetapkan untuk pengujian orkestrasi dan penjelasan Agent.</p>\n<label for=\"scenario\">Skenario Inquiry</label>\n<select id=\"scenario\" aria-label=\"Pilih skenario inquiry\"></select>\n<label for=\"provider\">Inference Engine</label>\n<select id=\"provider\"><option value=\"groq\">Groq · GPT-OSS 20B</option><option value=\"local\">ERP Engine · Baseline Analysis</option></select>\n<div class=\"row\" style=\"margin-top:18px\"><button id=\"run\" class=\"primary\">✦ Jalankan AI Analysis</button><span class=\"statusline\" id=\"status\" role=\"status\">Memeriksa kesiapan layanan...</span></div>\n<div class=\"notice\" style=\"margin-top:17px\">Pengujian ini menggunakan kasus dan katalog evaluasi terkontrol, bukan transaksi pelanggan maupun hasil stok aktual perusahaan. Keputusan produk tetap memerlukan review Technical dan Manager.</div>\n</section>\n<section class=\"card\">\n<div class=\"sectionhead\"><h2>Kesiapan Ekosistem</h2><span class=\"tag neutral\" id=\"readyflag\">Memeriksa</span></div>\n<div class=\"minirow\"><span>LLM Orchestration</span><strong id=\"modelstatus\">—</strong></div>\n<div class=\"minirow\"><span>Framework</span><strong>PydanticAI</strong></div>\n<div class=\"minirow\"><span>AI Modules</span><strong>4 Services</strong></div>\n<div class=\"minirow\"><span>Peran Agent</span><strong>Read-only advisory</strong></div>\n<div class=\"minirow\"><span>Katalog & Stok ERP</span><strong id=\"stockstatus\">Memuat data...</strong></div>\n<p class=\"muted\" style=\"margin-top:14px\">Katalog perusahaan ditampilkan sebagai referensi infrastruktur terpisah dan belum digunakan oleh skenario pengujian Agent ini.</p>\n</section>\n</div>\n<section class=\"card controls\" id=\"catalogAnalysis\">\n<div class=\"sectionhead\"><h2>Analisis Kandidat & Ketersediaan Stok ERP</h2><span class=\"tag neutral\">INTERNAL · READ-ONLY</span></div>\n<p class=\"sub\">Pencarian BM25 pada katalog PT Liliang, kemudian pemeriksaan persediaan fisik yang dikonfirmasi pengguna. Pemanggilan tool ini berjalan di server ERP dan tidak mengirim produk, SKU, atau stok ke Groq.</p>\n<p class=\"sub\"><a href=\"/ai/inquiry-advisor\" style=\"color:#2465b2;font-weight:800\">Buka Analisis Inquiry Sales yang Tersimpan →</a></p>\n<div class=\"row\"><button id=\"runCatalog\" class=\"primary\">Lihat Kandidat dari Katalog ERP</button>\n<input id=\"skuLookup\" class=\"stockinput\" placeholder=\"Cari stok SKU secara tepat\" maxlength=\"90\" aria-label=\"SKU stock lookup\">\n<button id=\"checkSku\" class=\"secondary\">Periksa SKU</button></div>\n<p id=\"catalogStatus\" class=\"statusline\" role=\"status\">Pilih skenario inquiry pada panel di atas, kemudian jalankan pencarian katalog.</p>\n<div id=\"catalogOutput\" class=\"inventorytable\" aria-live=\"polite\"></div>\n<p class=\"datascope\">Nilai stok dibaca dari tabel stok fisik perusahaan. Peringkat kandidat dan kesesuaian teknis tetap memerlukan verifikasi Technical. Tidak ada reservasi atau pengurangan persediaan.</p></section>\n<section class=\"result\" id=\"result\" aria-live=\"polite\">\n<div class=\"card\"><div class=\"sectionhead\"><h2>Hasil AI Agent · Inquiry Analysis</h2><span class=\"tag ok\" id=\"resultstatus\">Analisis Selesai</span></div>\n<div class=\"labeltitle\">Customer Requirement / Input</div><div class=\"inquiryquote\" id=\"inquiry\">—</div>\n<div class=\"row\" style=\"margin-top:14px\"><span class=\"tag neutral\" id=\"runmode\">—</span><span class=\"tag neutral\" id=\"tooltrace\">—</span><span class=\"tag warn\">Technical Review Required</span><button class=\"secondary rightalign\" id=\"exportEvidence\">Unduh Bukti UAT</button></div>\n</div>\n<div class=\"card\"><div class=\"sectionhead\"><h2>Executive AI Insight</h2><span class=\"tag ok\">LLM Orchestration</span></div><div id=\"analysis\" class=\"agentText\">—</div></div>\n<div class=\"resultgrid\">\n<section class=\"card module\"><div class=\"modhead\"><div class=\"icon\">01</div><div><h3>Requirement Interpretation</h3><small>AI-01 · Attribute extraction</small></div></div><div class=\"kv\" id=\"ai01\"></div><p class=\"muted\">Atribut yang belum dibuktikan tetap berstatus UNKNOWN.</p></section>\n<section class=\"card module\"><div class=\"modhead\"><div class=\"icon\">02</div><div><h3>Flavor Product Matching</h3><small>AI-02 · BM25 ranking</small></div></div><div class=\"tablewrap\"><table><thead><tr><th>Rank</th><th>SKU Kandidat</th><th>Nama Produk</th><th>BM25</th></tr></thead><tbody id=\"ai02\"></tbody></table></div><p class=\"muted\">Skor BM25 adalah relevansi leksikal, bukan probabilitas kelayakan produk.</p></section>\n<section class=\"card module\"><div class=\"modhead\"><div class=\"icon\">03</div><div><h3>Product Bundling Intelligence</h3><small>AI-03 · Association-rule baseline</small></div></div><div id=\"ai03\"></div><p class=\"muted\">Support, confidence dan lift dihitung dari dataset evaluasi.</p></section>\n<section class=\"card module\"><div class=\"modhead\"><div class=\"icon\">04</div><div><h3>Demand Forecasting</h3><small>AI-04 · Moving average (4 minggu)</small></div></div><div id=\"ai04\"></div><p class=\"muted\">Proyeksi demonstrasi, bukan estimasi penjualan aktual perusahaan.</p></section>\n</div>\n<div class=\"card\"><div class=\"sectionhead\"><h2>Research & Decision Governance</h2><span class=\"tag warn\">Human Review</span></div>\n<div class=\"footgrid\"><div class=\"notice\">Agent mengoordinasikan pemanggilan alat AI dan menyusun penjelasan. Peringkat SKU, aturan asosiasi, dan proyeksi tetap berasal dari layanan analisis terpisah.</div>\n<div class=\"notice\">Tidak ada otomatisasi approval, transaksi jual, pengurangan stok fisik, atau pengiriman Surat Jalan. Kelayakan produk dan akurasi model belum dinyatakan tervalidasi.</div></div>\n<div style=\"margin-top:14px\" class=\"muted\">Audit teknis dan provenance lengkap tersedia pada file bukti UAT yang dapat diunduh. Klaim pemanggilan empat tool hanya dicatat jika didukung jejak eksekusi aktual.</div>\n</div></section>\n<div class=\"footer\">PT Liliang International · Enterprise Architecture & Digital Blueprint · Research Integration Environment · <a href=\"https://github.com/adithekew/liliang-multi-ai-erp\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#2c6cad\">Source Code</a></div>\n</div></div></div>\n<script>\nconst token=sessionStorage.getItem(\"liliang_token\")||\"\";\nconst el=id=>document.getElementById(id);\nconst names={\n STRAWBERRY_DAIRY:\"Strawberry Flavor · Dairy Beverage\",\n MANGO_BEVERAGE:\"Mango Flavor · Beverage\",\n VANILLA_BAKERY:\"Vanilla Flavor · Bakery\",\n LEMON_POWDER:\"Lemon Flavor · Powder Request\",\n RASPBERRY_ABSTAIN:\"Raspberry · No Confident Candidate\"\n};\nlet lastResult=null;\nconst esc=v=>String(v===null||v===undefined?\"\":v).replace(/[&<>\"']/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\nconst fmt=n=>Number(n||0).toLocaleString(\"id-ID\",{maximumFractionDigits:2});\nfunction narrative(text){\n return esc(text||\"Tidak ada penjelasan tambahan dalam mode baseline.\")\n  .replace(/\\*\\*([^*]+)\\*\\*/g,\"<strong>$1</strong>\")\n  .replace(/\\n+/g,\"<br>\");\n}\nasync function api(path,options={}){\n const r=await fetch(path,{cache:\"no-store\",...options,headers:{\n  \"Authorization\":\"Bearer \"+token,\"Content-Type\":\"application/json\",...(options.headers||{})}});\n let d;\n try{d=await r.json()}catch{throw Error(\"Server mengembalikan respons tidak valid.\")}\n if(!r.ok)throw Error(typeof d.detail===\"string\"?d.detail:\"HTTP \"+r.status);\n return d;\n}\nfunction field(title,value){return '<div><small>'+esc(title)+'</small><b>'+esc(value===null||value===undefined||value===\"\"?\"UNKNOWN\":value)+'</b></div>'}\nfunction render(r){\n lastResult=r;\n const d=r.snapshot||{}, a=d[\"AI-01\"]||{},b=d[\"AI-02\"]||{},c=d[\"AI-03\"]||{},f=d[\"AI-04\"]||{};\n const out=a.output||{},top=b.top5||[],rules=c.rules||[],fc=f.forecast||{};\n el(\"result\").classList.add(\"show\");\n el(\"inquiry\").textContent=d.inquiry||\"—\";\n el(\"runmode\").textContent=r.mode===\"GROQ_FREE_SYNTHETIC\"?\"Groq LLM · Online\":\"ERP Baseline · Local\";\n let toolCalls=Array.isArray(r.tool_trace)?r.tool_trace:[];\n el(\"tooltrace\").textContent=r.all_four_tools_called?\"4/4 AI tools terverifikasi\":(toolCalls.length?toolCalls.length+\"/4 tools direkam · pemeriksaan belum lengkap\":\"Belum ada bukti tool calling Groq\");\n el(\"resultstatus\").textContent=r.mode===\"GROQ_FREE_SYNTHETIC\"?(r.all_four_tools_called?\"Groq & 4 Tools Confirmed\":\"Groq Response · Tool Audit Pending\"):\"Local Baseline Ready\";\n el(\"analysis\").innerHTML=narrative(r.llm_unverified || \"Hasil empat modul sudah diambil. Aktifkan Groq untuk penjelasan AI Agent berbasis LLM.\");\n el(\"ai01\").innerHTML=field(\"Flavor\",out.flavor)+field(\"Aplikasi\",out.application)+\n field(\"Bentuk Produk\",out.form)+field(\"Regulatory\",out.attributes?.regulatory?.value)+\n field(\"Halal Status\",out.attributes?.halal_status?.value);\n el(\"ai02\").innerHTML=top.length?top.map((x,i)=>'<tr><td>#'+esc(x.rank||i+1)+'</td><td><strong>'+esc(x.sku)+'</strong></td><td>'+esc(x.name)+'</td><td>'+esc(x.score)+'</td></tr>').join(\"\"):\n '<tr><td colspan=\"4\">Belum ditemukan kandidat dengan bukti yang memadai.</td></tr>';\n const applicable=rules.filter(x=>top.some(p=>p.sku===x.antecedent_sku));\n const relevant=applicable.length?applicable:rules.slice(0,3);\n el(\"ai03\").innerHTML=relevant.length?relevant.slice(0,4).map(x=>'<div class=\"minirow\"><span>'+esc(x.antecedent_sku)+' → '+esc(x.recommended_sku)+\n '</span><strong>Conf. '+fmt(Number(x.confidence)*100)+'%</strong></div>').join(\"\"):\"<p class='muted'>Tidak ada rekomendasi bundling pada kasus ini.</p>\";\n const pred=fc.forecast||[];\n el(\"ai04\").innerHTML='<div class=\"kv\">'+field(\"MAE\",fc.metrics?.rolling_mae_units)+\n field(\"WMAPE\",fc.metrics?.rolling_wmape_pct==null?null:fc.metrics.rolling_wmape_pct+\"%\")+'</div>'+\n '<div class=\"bars\">'+pred.map(p=>'<div class=\"barbox\"><strong>'+esc(p.predicted_units)+'</strong><div class=\"bar\" style=\"height:'+Math.max(18,Math.min(88,Number(p.predicted_units||0)))+'px\"></div><span>'+esc(p.week)+'</span></div>').join(\"\")+'</div>';\n el(\"result\").scrollIntoView({behavior:\"smooth\",block:\"start\"});\n}\nasync function start(){\n if(!token){el(\"status\").textContent=\"Login ERP terlebih dahulu di halaman Workspace.\";el(\"status\").classList.add(\"err\");el(\"run\").disabled=true;return}\n try{\n  const s=await api(\"/v1/agent/status\");\n  for(const id of s.case_ids){let option=document.createElement(\"option\");option.value=id;option.textContent=names[id]||id;el(\"scenario\").appendChild(option)}\n  el(\"modelstatus\").textContent=s.groq!==\"DISABLED\"?\"Groq GPT-OSS 20B · Ready\":\"ERP Baseline Available\";\n  el(\"readyflag\").textContent=s.groq!==\"DISABLED\"?\"Agent Connected\":\"Baseline Only\";\n  el(\"status\").textContent=s.groq!==\"DISABLED\"?\"Groq terkonfigurasi · jalankan UAT untuk verifikasi tool\":\"Mode Groq belum aktif; baseline tersedia\";\n  if(s.groq===\"DISABLED\")el(\"provider\").value=\"local\";\n  try{\n   const check=await api(\"/v1/agent/readiness\");\n   el(\"catalogStatus\").textContent=check.baseline_functional_checks_passed?\n    \"AI-01 sampai AI-04: pengujian fungsi lokal lulus · \"+fmt(check.physical_stock_skus)+\" SKU fisik tersedia di ERP.\":\n    \"Sebagian pemeriksaan fungsi AI belum lulus.\";\n  }catch(e){el(\"catalogStatus\").textContent=\"Pemeriksaan lokal belum tersedia: \"+e.message}\n\n  try{\n   const inventory=await api(\"/v1/catalog/stock-reference?limit=1\");\n   el(\"stockstatus\").textContent=fmt(inventory.physical_confirmed_skus||0)+\" SKU · Read-only\";\n  }catch(e){el(\"stockstatus\").textContent=\"Katalog ERP · Akses terbatas\"}\n }catch(e){el(\"status\").textContent=e.message;el(\"status\").classList.add(\"err\");el(\"run\").disabled=true}\n}\nel(\"run\").onclick=async()=>{\n el(\"run\").disabled=true;el(\"status\").textContent=\"Agent sedang memproses modul AI...\";\n try{\n  const d=await api(\"/v1/agent/demo\",{method:\"POST\",body:JSON.stringify({case_id:el(\"scenario\").value,provider:el(\"provider\").value})});\n  render(d);el(\"status\").textContent=\"Analisis selesai. Hasil tersedia di bawah.\";\n }catch(e){el(\"status\").textContent=\"Analisis belum berhasil: \"+e.message;el(\"status\").classList.add(\"err\")}\n finally{el(\"run\").disabled=false}\n};\nfunction catalogMessage(s,error=false){\n const target=el(\"catalogStatus\");target.textContent=s;target.classList.toggle(\"err\",error);\n}\nel(\"runCatalog\").onclick=async()=>{\n el(\"runCatalog\").disabled=true;catalogMessage(\"Mengambil kandidat BM25 dan data persediaan dari server ERP...\");\n try{\n  const response=await api(\"/v1/agent/catalog-preview\",{\n   method:\"POST\",body:JSON.stringify({case_id:el(\"scenario\").value})\n  });\n  const rows=response.candidates||[];\n  const header='<div class=\"tablewrap\"><table><thead><tr><th>Rank</th><th>SKU</th><th>Produk</th><th>BM25</th><th>Stok Fisik</th><th>Isi Kemasan</th><th>UoM</th></tr></thead><tbody>';\n  const body=rows.length?rows.map(x=>'<tr><td>#'+esc(x.rank)+'</td><td><strong>'+esc(x.sku)+\n   '</strong></td><td>'+esc(x.name)+'</td><td>'+esc(x.bm25_score)+'</td><td>'+\n   esc(x.stock_packages===null?\"UNKNOWN\":fmt(x.stock_packages)+\" \"+x.stock_uom)+'</td><td>'+\n   esc(x.pack_size===null?\"Belum ditetapkan\":fmt(x.pack_size)+\" \"+(x.pack_content_uom||\"\"))+\n   '</td><td>'+esc(x.package_mapping)+'</td></tr>').join(\"\"):\n   '<tr><td colspan=\"7\">Tidak ditemukan kandidat dengan kecocokan awal memadai.</td></tr>';\n  el(\"catalogOutput\").innerHTML=header+body+'</tbody></table></div>';\n  catalogMessage(\"Katalog ERP: \"+fmt(response.catalog_rows_considered)+\" SKU dianalisis secara lokal; \"+\n   rows.length+\" kandidat awal. Tidak ada data dikirim ke LLM.\");\n }catch(e){catalogMessage(\"Pemeriksaan katalog gagal: \"+e.message,true)}\n finally{el(\"runCatalog\").disabled=false}\n};\nel(\"checkSku\").onclick=async()=>{\n const sku=el(\"skuLookup\").value.trim();\n if(!sku){catalogMessage(\"Masukkan SKU yang ingin diperiksa.\",true);return}\n el(\"checkSku\").disabled=true;\n try{\n  const d=await api(\"/v1/agent/stock/\"+encodeURIComponent(sku));\n  el(\"catalogOutput\").innerHTML='<div class=\"kv\">'+\n   field(\"SKU\",d.sku)+field(\"Produk\",d.product)+\n   field(\"Saldo kemasan fisik\",d.stock_packages===null?\"UNKNOWN\":fmt(d.stock_packages)+\" \"+d.package_uom)+\n   field(\"Isi per kemasan\",d.pack_size===null?\"Belum ditetapkan\":fmt(d.pack_size)+\" \"+(d.pack_content_uom||\"\"))+\n   field(\"Konfirmasi fisik\",d.stock_status)+field(\"Status satuan\",d.package_mapping_status)+'</div>';\n  catalogMessage(\"Data stok dibaca langsung dari ERP tanpa memanggil Groq.\");\n }catch(e){catalogMessage(\"Pemeriksaan SKU gagal: \"+e.message,true)}\n finally{el(\"checkSku\").disabled=false}\n};\nel(\"exportEvidence\").onclick=()=>{\n if(!lastResult)return;\n const file=new Blob([JSON.stringify(lastResult,null,2)],{type:\"application/json\"});\n const url=URL.createObjectURL(file),link=document.createElement(\"a\");\n link.href=url;link.download=\"Liliang_AI_Agent_UAT_Evidence.json\";\n document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);\n};\nstart();\n</script></body></html>"
